package com.example.todo.config; import com.example.todo.entity.User; import com.example.todo.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; @Configuration @RequiredArgsConstructor public class DataInitializer {@Bean CommandLineRunner seed(UserRepository r,PasswordEncoder e){return a->{if(!r.existsByUsername("demo"))r.save(User.builder().username("demo").password(e.encode("password")).build());};}}
